package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="mandates")
public class Mandate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="director_id") private Long directorId; @Column(name="vice_director_id") private Long viceDirectorId; @Column(name="start_date") private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getDirectorId(){return directorId;} public void setDirectorId(Long directorId){this.directorId=directorId;} public Long getViceDirectorId(){return viceDirectorId;} public void setViceDirectorId(Long viceDirectorId){this.viceDirectorId=viceDirectorId;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate startDate){this.startDate=startDate;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate endDate){this.endDate=endDate;} }
